use vstd::prelude::*;

verus! {

fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> (res: Vec<i32>)
    requires
        s1.len() == s2.len(),
        s2.len() == s3.len(),
        // 0 <= 3n <= i32::MAX (stated assumption)
        3 * s1.len() <= i32::MAX as nat,
    ensures
        res.len() == 3 * s1.len(),
        // Index-by-index interleaving: (s1[i], s2[i], s3[i]) for each i
        forall|i: int|
            0 <= i < s1.len() as int ==>
                res[(3 * i) as int]     == s1[i] &&
                res[(3 * i + 1) as int] == s2[i] &&
                res[(3 * i + 2) as int] == s3[i],
{
    let n = s1.len();
    let mut out: Vec<i32> = Vec::new();
    out.reserve(3 * n);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            out.len() == 3 * i,
            forall|j: int|
                0 <= j < i as int ==>
                    out[(3 * j) as int]     == s1[j] &&
                    out[(3 * j + 1) as int] == s2[j] &&
                    out[(3 * j + 2) as int] == s3[j],
    {
        out.push(s1[i]);
        out.push(s2[i]);
        out.push(s3[i]);
        i += 1;
    }

    out
}

} // verus!